<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3'; import { reactive } from 'vue'; import ErpLayout from '@/Layouts/ErpLayout.vue'; import type { BankStatementSummary, BranchOption, PaginationMeta, TreasuryAccountOption } from '@/Types/treasury'; defineOptions({layout:ErpLayout});
const props=defineProps<{statements:{data:BankStatementSummary[];meta:PaginationMeta};filters:{search:string;status:string;branch_id:number|null;bank_account_id:number|null;per_page:number};branches:BranchOption[];bankAccounts:TreasuryAccountOption[];can:{import:boolean}}>();const filters=reactive({...props.filters});const apply=(page=1):void=>router.get(route('bank-statements.index'),{...filters,page},{preserveState:true,replace:true});const money=(v:string):string=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:6}).format(Number(v));const remove=(id:number):void=>{if(window.confirm('Delete this imported statement?'))router.delete(route('bank-statements.destroy',id));};
</script>
<template><Head title="Bank Statements"/><div class="space-y-6"><div class="flex justify-between"><div><h1 class="text-2xl font-semibold">Bank Statements</h1><p class="mt-1 text-sm text-gray-500">Imported bank activity ready for reconciliation.</p></div><Link v-if="can.import" :href="route('bank-statements.create')" class="h-fit rounded-lg bg-brand-500 px-4 py-2.5 text-sm text-white">Import Statement</Link></div><div class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><div class="grid gap-4 md:grid-cols-4"><input v-model="filters.search" placeholder="Reference or filename" class="h-11 rounded-lg border px-3 dark:border-gray-700"/><select v-model="filters.branch_id" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option :value="null">All branches</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select><select v-model="filters.bank_account_id" class="h-11 rounded-lg border px-3 dark:border-gray-700"><option :value="null">All bank accounts</option><option v-for="a in bankAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select><button class="rounded-lg bg-brand-500 text-sm text-white" @click="apply()">Apply</button></div></div><div class="overflow-hidden rounded-2xl border bg-white dark:border-gray-800 dark:bg-gray-900"><div class="overflow-x-auto"><table class="min-w-[980px] w-full"><thead class="bg-gray-50 dark:bg-white/[.03]"><tr><th class="p-4 text-left text-xs uppercase text-gray-500">Statement</th><th class="p-4 text-left text-xs uppercase text-gray-500">Account</th><th class="p-4 text-left text-xs uppercase text-gray-500">Period</th><th class="p-4 text-right text-xs uppercase text-gray-500">Opening</th><th class="p-4 text-right text-xs uppercase text-gray-500">Closing</th><th class="p-4 text-center text-xs uppercase text-gray-500">Lines</th><th class="p-4 text-right text-xs uppercase text-gray-500">Actions</th></tr></thead><tbody class="divide-y dark:divide-gray-800"><tr v-for="s in statements.data" :key="s.id"><td class="p-4"><Link :href="route('bank-statements.show',s.id)" class="font-medium text-brand-600">{{s.statement_reference}}</Link><p class="text-xs text-gray-500">{{s.source_filename}}</p></td><td class="p-4 text-sm">{{s.bank_account?.code}} — {{s.bank_account?.name}}<p class="text-xs text-gray-500">{{s.branch?.name}}</p></td><td class="p-4 text-sm">{{s.period_start}} to {{s.period_end}}</td><td class="p-4 text-right text-sm">{{money(s.opening_balance)}}</td><td class="p-4 text-right font-semibold">{{money(s.closing_balance)}}</td><td class="p-4 text-center">{{s.line_count}}</td><td class="p-4 text-right"><button v-if="s.can.delete" class="text-sm text-error-600" @click="remove(s.id)">Delete</button></td></tr><tr v-if="statements.data.length===0"><td colspan="7" class="p-12 text-center text-sm text-gray-500">No bank statements found.</td></tr></tbody></table></div><div class="flex justify-between border-t p-4 text-sm dark:border-gray-800"><span>{{statements.meta.total}} statements</span><div class="flex gap-2"><button :disabled="statements.meta.current_page<=1" class="rounded border px-3 py-1 disabled:opacity-50" @click="apply(statements.meta.current_page-1)">Previous</button><button :disabled="statements.meta.current_page>=statements.meta.last_page" class="rounded border px-3 py-1 disabled:opacity-50" @click="apply(statements.meta.current_page+1)">Next</button></div></div></div></div></template>
